export function registerPageInitializer(layouts, initialize) {
  let initialized = false;

  function initializeCurrentPage() {
    if (initialized || !layouts.includes(document.body.dataset.pageLayout)) {
      return;
    }

    initialize();
    initialized = true;
  }

  document.addEventListener('turbo:before-render', () => {
    initialized = false;
  });
  document.addEventListener('turbo:load', initializeCurrentPage);
  initializeCurrentPage();
}
